#!/usr/bin/env node
// MCP server for own-the-canvas: hands component data to the user's AI tool over stdio.
// Data = skills/own-the-canvas/components.json, generated by scripts/gen-ai-docs.mjs at build time.
// ponytail: hand-rolled JSON-RPC (newline-delimited stdio) so the package stays zero-dependency.
// Covers initialize, ping, tools/list and tools/call only; switch to @modelcontextprotocol/sdk if we
// ever need resources, prompts or HTTP transport.
import { readFileSync, realpathSync } from "node:fs";
import { createInterface } from "node:readline";
import { fileURLToPath } from "node:url";

const DATA = JSON.parse(
  readFileSync(new URL("../skills/own-the-canvas/components.json", import.meta.url), "utf8"),
);
const { version } = JSON.parse(readFileSync(new URL("../package.json", import.meta.url), "utf8"));

const TOOLS = [
  {
    name: "list_components",
    description:
      "List every own-the-canvas React component with its mood tags and a one-line description, plus the library's usage rules. Call this first, then pick the components whose mood fits the user's request.",
    inputSchema: { type: "object", properties: {} },
  },
  {
    name: "get_component",
    description:
      "Get one own-the-canvas component's exact props, defaults, presets and an import example. Call before writing code that uses it; only use props it lists.",
    inputSchema: {
      type: "object",
      properties: { name: { type: "string", description: 'Component name, e.g. "MoonlitSea"' } },
      required: ["name"],
    },
  },
];

const text = (t, isError = false) => ({ content: [{ type: "text", text: t }], ...(isError && { isError }) });

function callTool(name, args = {}) {
  if (name === "list_components") {
    const list = DATA.components.map((c) => `- ${c.name} [${c.moods.join(", ")}]: ${c.lead}`).join("\n");
    return text(`${DATA.usage}\n## Components\n\n${list}\n`);
  }
  if (name === "get_component") {
    const want = String(args.name ?? "").toLowerCase();
    const c = DATA.components.find((x) => x.name.toLowerCase() === want);
    if (c) return text(c.markdown);
    return text(`No component named "${args.name}". Available: ${DATA.components.map((x) => x.name).join(", ")}`, true);
  }
  return null;
}

// Returns the JSON-RPC response for one message, or undefined for notifications.
function handle(msg) {
  const { id, method, params } = msg;
  if (id === undefined) return undefined;
  const ok = (result) => ({ jsonrpc: "2.0", id, result });
  const fail = (code, message) => ({ jsonrpc: "2.0", id, error: { code, message } });

  switch (method) {
    case "initialize":
      return ok({
        protocolVersion: params?.protocolVersion ?? "2025-06-18",
        capabilities: { tools: {} },
        serverInfo: { name: "own-the-canvas", version },
        instructions:
          "Use for animated canvas backgrounds and effects in React. Call list_components, choose by mood, then get_component before writing code.",
      });
    case "ping":
      return ok({});
    case "tools/list":
      return ok({ tools: TOOLS });
    case "tools/call":
      return ok(callTool(params?.name, params?.arguments) ?? text(`Unknown tool: ${params?.name}`, true));
    default:
      return fail(-32601, `Method not found: ${method}`);
  }
}

// realpath: npx runs bins through a symlink in node_modules/.bin
if (process.argv[1] && fileURLToPath(import.meta.url) === realpathSync(process.argv[1])) {
  createInterface({ input: process.stdin }).on("line", (line) => {
    if (!line.trim()) return;
    let res;
    try {
      res = handle(JSON.parse(line));
    } catch {
      res = { jsonrpc: "2.0", id: null, error: { code: -32700, message: "Parse error" } };
    }
    if (res) process.stdout.write(JSON.stringify(res) + "\n");
  });
}
